            State := 0;
        ELSE
            MotorDown := TRUE;
        END_IF;

    3:
        IF CallUp AND DoorClosed AND NOT AtTop THEN
            State := 1;
        ELSIF AtBottom OR NOT DoorClosed THEN
            State := 0;
        ELSE
            MotorUp := TRUE;
        END_IF;

END_CASE;

END_PROGRAM

PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    Bottom := 0;
    Up := 1;
    Top := 2;
    Down := 3;
END_VAR

CASE State OF
    Bottom:
        IF CallUp AND DoorClosed THEN
            State := Up;
        ELSIF NOT DoorClosed OR AtBottom THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    Up:
        IF AtTop OR (CallDown AND DoorClosed) THEN
            State := Top;
        ELSIF NOT DoorClosed OR AtBottom THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    Top:
        IF CallDown AND DoorClosed THEN
            State := Down;
        ELSIF NOT DoorClosed OR AtTop THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;

    Down:
        IF AtBottom OR (CallUp AND DoorClosed) THEN
            State := Bottom;
        ELSIF NOT DoorClosed OR AtTop THEN
            MotorUp := FALSE;
            MotorDown := FALSE;
        END_IF;
END_CASE;

CASE State OF
    Bottom:
        MotorUp := TRUE;
        MotorDown := FALSE;
    Up:
        MotorUp := TRUE;
        MotorDown := FALSE;
    Top:
        MotorUp := FALSE;
        MotorDown := TRUE;
    Down:
        MotorUp := FALSE;
        MotorDown := TRUE;
END_CASE;

END_PROGRAM

