    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME literal := T#3s;
END_VAR
VAR TON
    T1, T2;
END_VAR

T1(IN := EStop OR (Level < LIQ_MIN AND (State = 1 OR State = 4)), PT := T#0s);
T2(IN := EStop OR (Level < LIQ_MIN AND (State = 1 OR State = 4)), PT := PT_REACT);

CASE State OF
    0:  // Idle
        IF StartBatch AND EStop AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1:  // Fill
        IF T1.Q OR Level >= LVL_HIGH THEN
            State := 2;
        ELSE
            FillValve := TRUE;
        END_IF;

    2:  // Heat
        IF T1.Q OR Temp >= TEMP_SET THEN
            State := 3;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    3:  // React
        IF T1.Q OR T2.TimedOut THEN
            State := 4;
        ELSE
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    4:  // Drain
        IF T1.Q OR Level <= LVL_LOW THEN
            State := 0;
        ELSE
            DrainValve := TRUE;
        END_IF;
END_CASE;

IF NOT EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF Level < LIQ_MIN AND (State = 1 OR State = 4) THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

