        ELSIF StartPB AND EStop THEN
            State := STARTING;
        END_IF;
    STARTING:
        IF (NOT EStop) OR StopPB THEN
            State := OFF;
        ELSIF EStop AND State = STARTING AND Ticks >= PT_SEQ THEN
            State := RUNNING;
        END_IF;
    RUNNING:
        IF (NOT EStop) OR StopPB THEN
            State := OFF;
        END_IF;
END_CASE;

